}

/** 长度前缀令牌：{长度}:{原文}；空串为 "0:"，与缺字段/null 可区分。 */
private static String token(String value) {
    String safe = value == null ? "" : value;
    return safe.length() + ":" + safe;
}

private static String sha256(String canonical) {
    try {
