 * 跨许可版本或出现缺测/不合规小时立即断段；段长超过该许可最大连续小时数即专项异常。
 */
private void recomputeSegmentAnomalies(String code, LocalDateTime now) {
    repo.deleteAnomalies(code);
    // 仅已复核冻结的合规溢流小时参与“最长连续段”：跨许可版本或中间缺一个整点槽位（缺点）立即断段。
    List<Map<String, Object>> compliant = repo.findOverflowMarks(code).stream()
            .filter(m -> "FROZEN_COMPLIANT".equals(m.get("status")))
            .toList();

    int i = 0;
    while (i < compliant.size()) {
        Map<String, Object> first = compliant.get(i);
        Integer permitVersion = intOrNull(first.get("frozen_permit_version"));
        if (permitVersion == null) {
            permitVersion = intOrNull(first.get("candidate_permit_version"));
        }
        int j = i;
        while (j + 1 < compliant.size()) {
            Map<String, Object> cur = compliant.get(j);
            Map<String, Object> next = compliant.get(j + 1);
            LocalDateTime curHour = lt(cur.get("hour_utc"));
            LocalDateTime nextHour = lt(next.get("hour_utc"));
            Integer nextPermit = intOrNull(next.get("frozen_permit_version"));
            if (nextPermit == null) {
                nextPermit = intOrNull(next.get("candidate_permit_version"));
