        int length = j - i + 1;
        if (permitVersion != null) {
            Map<String, Object> permit = repo.findPermit(code, permitVersion);
            if (permit != null) {
                int limit = ((Number) permit.get("max_consecutive_overflow_hours")).intValue();
                if (length > limit) {
                    LocalDateTime segFrom = lt(first.get("hour_utc"));
                    LocalDateTime segTo = lt(compliant.get(j).get("hour_utc")).plusHours(1);
