                    String detail = "连续合规溢流 " + length + " 小时，超过许可版本 " + permitVersion
                            + " 允许的最大连续 " + limit + " 小时（跨版本/缺点已断段）";
                    repo.insertAnomaly(code, "SEGMENT_TOO_LONG", anomalyFrom, globalSegTo, length, limit,
                            permitVersion, detail, now);
                }
            }
        }
        i = j + 1;
    }
